int foundry_gate_v1_type_find(const char *name) {
  static const char *const names[] = {"gatehouse", "postern", "tower_gate", "town_gate", "wooden_gate"};
  for (int i = 0; name && i < 5; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

int foundry_gate_v1_wall_find(const char *name) {
  static const char *const names[] = {"adobe_wall", "brick_wall", "curtain", "drystone_wall", "dwarf_rampart", "earth_bank", "keep_wall", "living_wall", "palisade", "stone_circle", "town_wall"};
  for (int i = 0; name && i < 11; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

int foundry_gate_v1_condition_find(const char *name) {
  static const char *const names[] = {"intact", "ruin"};
  for (int i = 0; name && i < 2; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

int foundry_gate_v1_season_find(const char *name) {
  static const char *const names[] = {"winter", "spring", "summer", "fall"};
  for (int i = 0; name && i < 4; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

int foundry_gate_v1_detail_find(const char *name) {
  static const char *const names[] = {"high", "medium", "low"};
  for (int i = 0; name && i < 3; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

foundry_status foundry_gate_v1_start_door(foundry_runtime *rt, foundry_instance instance) {
  return foundry_status_of(rt->world.trigger(instance, &kType, 0));
}

foundry_status foundry_gate_v1_get_result(foundry_runtime *rt, foundry_instance instance, foundry_gate_v1_result *out) {
  uint32_t bits = 0;
  const runtime::Status st = rt->world.result(instance, bits);
  if (st != runtime::Status::ok) return foundry_status_of(st);
  if (!out) return FOUNDRY_OK;
  out->door_over = (bits & (1u << 0)) != 0;
  out->ready = (bits & runtime::World::kResultReady) != 0;
  return FOUNDRY_OK;
}

